package main

import (
	"debug/buildinfo" // https://pkg.go.dev/debug/buildinfo — Package buildinfo provides access to information embedded in a Go binary about how it was built.
	"debug/dwarf"     // https://pkg.go.dev/debug/dwarf — Package dwarf provides access to DWARF debugging information loaded from executable files.
	"debug/elf"       // https://pkg.go.dev/debug/elf — Package elf implements access to ELF object files.
	"debug/gosym"     // https://pkg.go.dev/debug/gosym — Package gosym implements access to the Go symbol and line number tables embedded in Go binaries generated by the gc compiler.
	"debug/macho"     // https://pkg.go.dev/debug/macho — Package macho implements access to Mach-O object files.
	"debug/pe"        // https://pkg.go.dev/debug/pe — Package pe implements access to PE (Microsoft Windows Portable Executable) files.
	"debug/plan9obj"  // https://pkg.go.dev/debug/plan9obj — Package plan9obj implements access to Plan 9 a.out object files.
	"fmt"             // https://pkg.go.dev/fmt — Package fmt implements formatted I/O with functions analogous to C's printf and scanf.
	"log"             // https://pkg.go.dev/log — Package log implements a simple logging package.
	"os"              // https://pkg.go.dev/os — Package os provides a platform-independent interface to operating system functionality.
)

// The debug/* packages parse compiled binaries. buildinfo works
// cross-platform; elf/macho/pe/plan9obj each speak one object format
// (only the one matching the current binary will parse successfully);
// dwarf and gosym extract debug info once you have an ELF/Mach-O file.
func runDebug() {
	self, err := os.Executable()
	if err != nil {
		log.Fatal(err)
	}
	debugBuildinfo(self)
	debugFormats(self)
	debugElfSections(self)
	debugDwarf(self)
	debugGosym(self)
}

func debugBuildinfo(path string) {
	bi, err := buildinfo.ReadFile(path)
	if err != nil {
		fmt.Println("buildinfo err:", err)
		return
	}
	fmt.Println("=== buildinfo ===")
	fmt.Println("go version:", bi.GoVersion)
	fmt.Println("main path: ", bi.Main.Path)
}

func debugFormats(path string) {
	// Each *.Open tries to parse the file in its native format. Only
	// the one matching the current OS's binary format will succeed.
	fmt.Println("\n=== format detection ===")
	if f, err := elf.Open(path); err == nil {
		fmt.Printf("elf:      %s %s, %d sections\n", f.Class, f.Machine, len(f.Sections))
		f.Close()
	} else {
		fmt.Println("elf:      not an ELF file")
	}
	if f, err := macho.Open(path); err == nil {
		fmt.Printf("macho:    cpu=%s, %d sections\n", f.Cpu, len(f.Sections))
		f.Close()
	} else {
		fmt.Println("macho:    not a Mach-O file")
	}
	if f, err := pe.Open(path); err == nil {
		fmt.Printf("pe:       machine=0x%x, %d sections\n", f.Machine, len(f.Sections))
		f.Close()
	} else {
		fmt.Println("pe:       not a PE file")
	}
	if f, err := plan9obj.Open(path); err == nil {
		fmt.Printf("plan9obj: magic=%d, %d sections\n", f.Magic, len(f.Sections))
		f.Close()
	} else {
		fmt.Println("plan9obj: not a Plan 9 a.out file")
	}
}

func debugElfSections(path string) {
	f, err := elf.Open(path)
	if err != nil {
		return
	}
	defer f.Close()
	fmt.Println("\n=== elf sections (first 5) ===")
	for i, s := range f.Sections {
		if i >= 5 {
			break
		}
		fmt.Printf("  %-24s addr=0x%08x size=%d\n", s.Name, s.Addr, s.Size)
	}
}

func debugDwarf(path string) {
	f, err := elf.Open(path)
	if err != nil {
		return
	}
	defer f.Close()
	d, err := f.DWARF()
	if err != nil {
		fmt.Println("\n=== dwarf ===\n  not available:", err)
		return
	}
	fmt.Println("\n=== dwarf (first 3 compilation units) ===")
	r := d.Reader()
	shown := 0
	for shown < 3 {
		e, err := r.Next()
		if err != nil || e == nil {
			break
		}
		if e.Tag == dwarf.TagCompileUnit {
			name, _ := e.Val(dwarf.AttrName).(string)
			fmt.Println("  CU:", name)
			shown++
		}
		r.SkipChildren()
	}
}

func debugGosym(path string) {
	f, err := elf.Open(path)
	if err != nil {
		return
	}
	defer f.Close()

	text := f.Section(".text")
	pclntab := f.Section(".gopclntab")
	if text == nil || pclntab == nil {
		fmt.Println("\n=== gosym ===\n  .text or .gopclntab missing")
		return
	}
	data, err := pclntab.Data()
	if err != nil {
		return
	}
	tab, err := gosym.NewTable(nil, gosym.NewLineTable(data, text.Addr))
	if err != nil {
		fmt.Println("\n=== gosym ===\n  err:", err)
		return
	}
	fmt.Println("\n=== gosym (main.main location) ===")
	if fn := tab.LookupFunc("main.main"); fn != nil {
		file, line, _ := tab.PCToLine(fn.Entry)
		fmt.Printf("  main.main at %s:%d\n", file, line)
	}
}
